"""Audit held evidence; restore only original price points exactly witnessed by official rows."""
import calendar,collections,csv,gzip,hashlib,json
from decimal import Decimal
from pathlib import Path
R=Path(__file__).resolve().parents[1];D=R/'docs/price-kpi-audit-v1';D.mkdir(exist_ok=True)
load=lambda p:json.loads(p.read_text())
data=load(R/'src/generated/market_catalogue_public.json');legacy=load(R/'src/generated/market_public.json');pulse=load(R/'src/generated/trade_pulse_public.json');cn={c['cn8']:c for c in load(R/'src/generated/trade_cn_public.json')['entities']}
source=R/'docs/market-commercial-v4/evidence/comext-normalized-public.jsonl.gz';digest=hashlib.sha256(source.read_bytes()).hexdigest();assert digest==pulse['source_artifact_sha256']
with gzip.open(source,'rt') as f:rows=[json.loads(l) for l in f]
