print(json.dumps({'candidate_decisions':collections.Counter(a['decision'] for a in audits),'price_cards':sum(bool(c['price_observations']) for c in data['cards']),'snapshot':len(snapshot),'period':period,'tonnes':str(tonnes),'observations':len(subset)}))
